class Key:
    def __init__(self, v):
        self.v = v
    def __eq__(self, other):
        return self.v == other.v
    def __hash__(self):
        return hash(self.v)

k = Key(1)
s = {k}
k.v = 2
print(k in s, Key(1) in s)
```

